files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --input-bg: #0f3460;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
  background-image: radial-gradient(circle, #1f1f3a 1px, transparent 1px);
  background-size: 20px 20px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  image-rendering: pixelated;
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.subtitle {
  text-align: center;
  color: var(--muted);
  font-size: 0.95rem;
  margin-bottom: 24px;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  font-size: 0.95rem;
  letter-spacing: 0.5px;
}

input {
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--input-bg);
  border: 3px solid #2a2a4a;
  border-radius: 0;
  color: var(--text);
  outline: none;
  transition: border-color 0.1s;
}

input:hover {
  border-color: var(--accent);
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input::placeholder {
  color: #666;
}

button {
  width: 100%;
  padding: 14px;
  font-size: 1.1rem;
  font-family: var(--font);
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  background: var(--accent);
  color: #fff;
  border: 3px solid transparent;
  border-radius: 0;
  cursor: pointer;
  margin-top: 8px;
  transition: background 0.1s, transform 0.05s;
}

button:hover {
  background: #f05a75;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: translate(2px, 2px);
  background: #c73550;
}

.result {
  margin-top: 24px;
  padding: 16px;
  background: var(--input-bg);
  border: 3px solid #2a2a4a;
  text-align: center;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
}

.bmi-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 2px;
}

.bmi-category {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.bmi-category.underweight { color: #5bc0eb; }
.bmi-category.normal { color: #9bc53d; }
.bmi-category.overweight { color: #fde74c; }
.bmi-category.obese { color: #e94560; }

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.4rem; }
  .bmi-value { font-size: 1.6rem; }
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('bmi-form');
  const heightInput = document.getElementById('height');
  const weightInput = document.getElementById('weight');
  const resultDiv = document.getElementById('result');
  const bmiValueSpan = resultDiv.querySelector('.bmi-value');
  const categorySpan = resultDiv.querySelector('.bmi-category');

  function getCategory(bmi) {
    if (bmi < 18.5) return { label: 'Underweight', cls: 'underweight' };
    if (bmi < 25) return { label: 'Normal', cls: 'normal' };
    if (bmi < 30) return { label: 'Overweight', cls: 'overweight' };
    return { label: 'Obese', cls: 'obese' };
  }

  function showError(message) {
    bmiValueSpan.textContent = '--';
    categorySpan.textContent = message;
    categorySpan.className = 'bmi-category';
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const height = parseFloat(heightInput.value);
    const weight = parseFloat(weightInput.value);

    if (!height || height <= 0 || !weight || weight <= 0) {
      showError('Enter valid positive numbers');
      return;
    }

    const heightM = height / 100;
    const bmi = weight / (heightM * heightM);
    const rounded = Math.round(bmi * 10) / 10;
    const category = getCategory(rounded);

    bmiValueSpan.textContent = rounded.toFixed(1);
    categorySpan.textContent = category.label;
    categorySpan.className = 'bmi-category ' + category.cls;
  });
});
